changeSet.sql:
CREATE SEQUENCE pm_halyk_invoice_seq MINVALUE 100000 MAXVALUE 999999 START WITH 100000 NO CYCLE;
CREATE TABLE common_outbox (
 id uuid PRIMARY KEY, payload text NOT NULL, available_at timestamp with time zone NOT NULL,
 attempts integer NOT NULL DEFAULT 0, delivered_at timestamp with time zone
);
CREATE INDEX ix_common_outbox_due ON common_outbox(available_at) WHERE delivered_at IS NULL;
CREATE TABLE common_financial_audit (
 id uuid PRIMARY KEY, context varchar(40) NOT NULL, aggregate_id uuid NOT NULL, actor_id bigint,
 action varchar(120) NOT NULL, occurred_at timestamp with time zone NOT NULL, details varchar(200)
);
CREATE INDEX ix_financial_audit_aggregate ON common_financial_audit(aggregate_id,occurred_at);
CREATE TABLE oc_checkout (id uuid PRIMARY KEY,event_id uuid NOT NULL,owner_id bigint NOT NULL,status varchar(40) NOT NULL,snapshot text NOT NULL);
CREATE INDEX ix_oc_checkout_owner ON oc_checkout(owner_id);
CREATE INDEX ix_oc_checkout_active ON oc_checkout(status) WHERE status IN ('IN_PROGRESS','AWAITING_PAYMENT');
CREATE TABLE oc_saga (id uuid PRIMARY KEY REFERENCES oc_checkout(id),snapshot text NOT NULL);
CREATE TABLE oc_order (id uuid PRIMARY KEY,event_id uuid NOT NULL,owner_id bigint NOT NULL,snapshot text NOT NULL);
CREATE INDEX ix_oc_order_owner ON oc_order(owner_id);
CREATE TABLE pm_payment_work (
 id uuid PRIMARY KEY,order_id uuid UNIQUE,event_id uuid NOT NULL,organizer_id bigint NOT NULL,payer_id bigint NOT NULL,
 purpose varchar(20) NOT NULL CHECK(purpose IN ('TICKET','ACTIVATION')),invoice_id varchar(15) NOT NULL UNIQUE,
 snapshot text NOT NULL,next_poll timestamp with time zone NOT NULL,lease_until timestamp with time zone,
 CHECK((purpose='TICKET' AND order_id IS NOT NULL) OR (purpose='ACTIVATION' AND order_id IS NULL))
);
CREATE INDEX ix_pm_payment_due ON pm_payment_work(next_poll);
CREATE INDEX ix_pm_payment_organizer ON pm_payment_work(organizer_id);
CREATE TABLE pm_event_activation (
 event_id uuid PRIMARY KEY,organizer_id bigint NOT NULL,status varchar(30) NOT NULL,
 payment_id uuid NOT NULL REFERENCES pm_payment_work(id),fee_payment_id uuid REFERENCES pm_payment_work(id),
 created_at timestamp with time zone NOT NULL,verification_simulated boolean NOT NULL,terms_version varchar(50) NOT NULL,
 suspended_at timestamp with time zone,suspension_reason varchar(200)
);
CREATE TABLE pm_ledger (
 operation_key varchar(100) PRIMARY KEY,payment_id uuid NOT NULL REFERENCES pm_payment_work(id),event_id uuid NOT NULL,
 organizer_id bigint NOT NULL,kind varchar(20) NOT NULL CHECK(kind IN ('CHARGE','REFUND')),
 amount numeric(19,2) NOT NULL CHECK(amount>0),fee numeric(19,2) NOT NULL CHECK(fee>=0),
 created_at timestamp with time zone NOT NULL DEFAULT current_timestamp
);
CREATE INDEX ix_pm_ledger_organizer ON pm_ledger(organizer_id);
CREATE TABLE pm_refund_history (
 id uuid PRIMARY KEY,payment_id uuid NOT NULL REFERENCES pm_payment_work(id),reason varchar(200),
 requested_at timestamp with time zone NOT NULL,status varchar(30) NOT NULL,provider_reference varchar(100),failure_reason varchar(200),completed_at timestamp with time zone
);
CREATE TABLE pm_payment_session (
 payment_id uuid PRIMARY KEY REFERENCES pm_payment_work(id),claim_id uuid NOT NULL,claimed_until timestamp with time zone NOT NULL,
 encrypted_payload text,expires_at timestamp with time zone
);
